function pickChanges(body) {
  for (const key of Object.keys(body ?? {})) {
    if (key !== "title" && key !== "done") throw new Error(`unknown field "${key}"`);
  }
  const changes = {};
  if (body?.title !== undefined) changes.title = String(body.title).trim();
  if (body?.done !== undefined) {
    if (typeof body.done !== "boolean") throw new Error("done must be true or false");
    changes.done = body.done;
  }
  return changes;
}

for (const body of [{ done: true }, { title: "  Call Ada " }, { id: 7 }, { done: "yes" }, {}]) {
  try {
    console.log(JSON.stringify(pickChanges(body)));
  } catch (error) {
    console.log(error.message);
  }
}

